import zlib
def score(program: str) -> float:
    g = {program[i:i + 3] for i in range(len(program) - 2)}
    n = max(1, len(g))
    v = sum(zlib.crc32(x.encode()) % 1000 for x in g) / (999.0 * n)
    return min(1.0, max(0.0, 0.5 + 8 * (v - 0.5)))

