        return 0.0
    n = [type(x).__name__ for x in ast.walk(t)]
    return min(1.0, len(set(n)) / (len(n) + 20) * 3)

def score(program: str) -> float:
    import ast
    try:
        tree = ast.parse(program)

        # Check if program defines score function
        has_score = any(
            isinstance(node, ast.FunctionDef) and node.name == 'score'
            for node in ast.walk(tree)
        )

        if not has_score:
            return 0.2

        # Measure program size
        node_count = len(list(ast.walk(tree)))

        # Larger programs get slight bonus
        if node_count > 100:
            return 0.8

        return 0.75
    except:
        return 0.0

